from __future__ import annotations

"""Plain dictionary views of actions, history events, and run results.

Callers that want to inspect or persist what an orchestration did read these.
They never recompute anything; they only flatten the in-memory objects into
JSON-friendly dictionaries and offer a couple of comparison helpers used to
check that two runs emitted the same action sequence.
"""

from replay_models import (
    Action,
    ActionType,
    HistoryEvent,
    OrchestrationResult,
)


def action_to_dict(action: Action) -> dict[str, object]:
    payload: dict[str, object] = {
        "action_type": action.action_type.value,
        "task_index": action.task_index,
    }
    if action.action_type == ActionType.CALL_ACTIVITY:
        payload["activity_name"] = action.activity_name
        payload["activity_input"] = action.activity_input
    else:
        payload["payload"] = action.payload
    return payload


def event_to_dict(event: HistoryEvent) -> dict[str, object]:
    return {
        "event_type": event.event_type.value,
        "task_index": event.task_index,
        "activity_name": event.activity_name,
        "activity_input": event.activity_input,
        "result": event.result,
    }


def result_to_dict(result: OrchestrationResult) -> dict[str, object]:
    return {
        "status": result.status,
        "instance_id": result.instance_id,
        "output": result.output,
        "replays": result.replays,
        "reason": result.reason,
        "actions": [action_to_dict(a) for a in result.actions],
        "action_count": len(result.actions),
    }


def action_sequence(result: OrchestrationResult) -> list[tuple]:
    """The ordered action fingerprints of a run, for equality checks."""

    return result.action_signatures()


def sequences_match(left: OrchestrationResult, right: OrchestrationResult) -> bool:
    """Whether two runs emitted the same ordered action sequence."""

    return action_sequence(left) == action_sequence(right)


def schedule_order(result: OrchestrationResult) -> list[str]:
    """The activity names in the order they were scheduled in this run."""

    return [
        a.activity_name
        for a in result.actions
        if a.action_type == ActionType.CALL_ACTIVITY
    ]


def scheduled_inputs(result: OrchestrationResult) -> list[object]:
    """The activity inputs in scheduling order."""

    return [
        a.activity_input
        for a in result.actions
        if a.action_type == ActionType.CALL_ACTIVITY
    ]

