from __future__ import annotations

"""Registry of activity functions the engine can invoke for real.

Activities are plain Python callables registered by name. They take a single
serializable input and return a serializable value. The engine calls them only
when an orchestrator schedules a task that has no recorded completion yet; on
replay the recorded value is fed back instead, so an activity is invoked at most
once per task index.

Activities are expected to be the place where side effects and non-deterministic
work live (a real timestamp, a generated id, a network call). The orchestrator
itself must stay deterministic. That split is the whole point of the model.
"""

from typing import Callable


class ActivityError(Exception):
    """Raised when an activity is missing or fails while being invoked."""


class ActivityRegistry:
    def __init__(self) -> None:
        self._activities: dict[str, Callable[[object], object]] = {}
        self._invocation_counts: dict[str, int] = {}

    def register(self, name: str, fn: Callable[[object], object]) -> None:
        if not isinstance(name, str) or not name.strip():
            raise ValueError("activity name is required")
        if not callable(fn):
            raise ValueError("activity must be callable")
        self._activities[name] = fn

    def activity(self, name: str):
        """Decorator form of :meth:`register`."""

        def _decorator(fn: Callable[[object], object]) -> Callable[[object], object]:
            self.register(name, fn)
            return fn

        return _decorator

    def has(self, name: str) -> bool:
        return name in self._activities

    def invoke(self, name: str, activity_input: object) -> object:
        """Run a registered activity once and return its value."""

        fn = self._activities.get(name)
        if fn is None:
            raise ActivityError(f"unknown activity: {name}")
        self._invocation_counts[name] = self._invocation_counts.get(name, 0) + 1
        try:
            return fn(activity_input)
        except ActivityError:
            raise
        except Exception as exc:  # noqa: BLE001 - wrap any activity failure
            raise ActivityError(f"activity {name} failed: {exc}") from exc

    def invocation_count(self, name: str) -> int:
        return self._invocation_counts.get(name, 0)

    def total_invocations(self) -> int:
        return sum(self._invocation_counts.values())

    def registered_names(self) -> list[str]:
        return sorted(self._activities)

    def reset_counts(self) -> None:
        self._invocation_counts.clear()

