from __future__ import annotations

"""Append-only history for a single orchestration instance.

History is the source of truth the engine replays against. It holds, in the
order they happened:

* a ``TASK_SCHEDULED`` event for every activity the orchestrator scheduled, and
* a ``TASK_COMPLETED`` event for every scheduled task that has produced a value.

On replay the engine reads the completed events and hands their results back to
the orchestrator keyed by task index. The order in which completions were
appended is preserved here, because real activities finish out of order and the
fan-in code is supposed to cope with that.
"""

from replay_models import (
    EventType,
    HistoryEvent,
    completed_event,
    scheduled_event,
)


class HistoryStore:
    def __init__(self) -> None:
        self._events: list[HistoryEvent] = []
        self._completed_indices: set[int] = set()
        self._scheduled_indices: set[int] = set()

    def record_scheduled(
        self, task_index: int, activity_name: str, activity_input: object
    ) -> HistoryEvent:
        event = scheduled_event(task_index, activity_name, activity_input)
        self._events.append(event)
        self._scheduled_indices.add(task_index)
        return event

    def record_completed(
        self, task_index: int, activity_name: str, result: object
    ) -> HistoryEvent:
        """Append a completion. Completions land in arrival order, not index."""

        event = completed_event(task_index, activity_name, result)
        self._events.append(event)
        self._completed_indices.add(task_index)
        return event

    def has_completion(self, task_index: int) -> bool:
        return task_index in self._completed_indices

    def is_scheduled(self, task_index: int) -> bool:
        return task_index in self._scheduled_indices

    def completion_events(self) -> list[HistoryEvent]:
        """Completed events in the order they were appended (arrival order)."""

        return [e for e in self._events if e.event_type == EventType.TASK_COMPLETED]

    def completions_by_index(self) -> dict[int, object]:
        """Map each completed task index to its recorded result value."""

        mapping: dict[int, object] = {}
        for event in self._events:
            if event.event_type == EventType.TASK_COMPLETED:
                mapping[event.task_index] = event.result
        return mapping

    def scheduled_events(self) -> list[HistoryEvent]:
        return [e for e in self._events if e.event_type == EventType.TASK_SCHEDULED]

    def events(self) -> list[HistoryEvent]:
        return list(self._events)

    def completed_count(self) -> int:
        return len(self._completed_indices)

    def scheduled_count(self) -> int:
        return len(self._scheduled_indices)

    def has_any_completions(self) -> bool:
        return bool(self._completed_indices)

    def outstanding_indices(self) -> list[int]:
        """Scheduled task indices that have not completed yet, in index order."""

        return sorted(self._scheduled_indices - self._completed_indices)

