from __future__ import annotations

"""Domain models for a small Durable-Functions-style orchestration engine.

The engine runs an *orchestrator function* by replaying it from the top every
time an activity it scheduled completes. On each replay the orchestrator emits a
sequence of ACTIONS: it schedules activities and, eventually, completes with a
result. The engine records that action sequence the first time through and, on
every later replay, the freshly emitted sequence must match the recorded one
exactly. If it diverges, the engine cannot line up recorded activity results
with the tasks the orchestrator is now awaiting, and the history is corrupted.

The objects here are plain value types. The deterministic context, the replay
runner, the activity registry, the history store, and the fan-in aggregator all
build on these.

Vocabulary:

* ``Action`` — one thing the orchestrator told the engine to do during a replay.
  Either schedule an activity (``call_activity``) or finish (``complete``).
* ``HistoryEvent`` — one recorded fact the engine knows: a task was scheduled,
  or a scheduled task completed with a value. History drives replay.
* ``Task`` — the handle the orchestrator gets back from ``call_activity``. It
  carries a stable index assigned in scheduling order.
* ``OrchestrationResult`` — the terminal output once every awaited task has a
  recorded result.
"""

from dataclasses import dataclass, field
from enum import Enum


class ActionType(str, Enum):
    CALL_ACTIVITY = "call_activity"
    COMPLETE = "complete"


class EventType(str, Enum):
    TASK_SCHEDULED = "task_scheduled"
    TASK_COMPLETED = "task_completed"


def _require_text(value: str, field_name: str) -> None:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} is required")


def _require_index(value: int, field_name: str) -> None:
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"{field_name} must be an int")
    if value < 0:
        raise ValueError(f"{field_name} must be non-negative")


@dataclass(frozen=True)
class Action:
    """One action emitted by the orchestrator during a single replay pass.

    For ``CALL_ACTIVITY`` the ``task_index`` is the stable index the engine
    assigned in scheduling order, ``activity_name`` the registered activity, and
    ``activity_input`` the serializable input. For ``COMPLETE`` the
    ``activity_name`` is empty and ``payload`` carries the terminal result.
    """

    action_type: ActionType
    task_index: int
    activity_name: str = ""
    activity_input: object = None
    payload: object = None

    def __post_init__(self) -> None:
        _require_index(self.task_index, "task_index")
        if self.action_type == ActionType.CALL_ACTIVITY:
            _require_text(self.activity_name, "activity_name")

    def signature(self) -> tuple:
        """A comparable fingerprint of this action.

        Two replays are deterministic only if the ordered list of these
        fingerprints is identical. The fingerprint deliberately includes the
        scheduled input, so an orchestrator that builds inputs from a wall clock
        or a random id produces a different fingerprint on replay.
        """

        if self.action_type == ActionType.CALL_ACTIVITY:
            return (
                self.action_type.value,
                self.task_index,
                self.activity_name,
                _freeze(self.activity_input),
            )
        return (self.action_type.value, self.task_index, _freeze(self.payload))


@dataclass(frozen=True)
class HistoryEvent:
    """One recorded fact about the orchestration, in the order it occurred."""

    event_type: EventType
    task_index: int
    activity_name: str = ""
    activity_input: object = None
    result: object = None

    def __post_init__(self) -> None:
        _require_index(self.task_index, "task_index")

    def is_completion(self) -> bool:
        return self.event_type == EventType.TASK_COMPLETED


@dataclass
class Task:
    """Handle returned by ``ctx.call_activity``.

    The orchestrator awaits these. ``index`` is assigned in scheduling order and
    is the only stable way to line a task up with its recorded result, because
    activities may complete in any order.
    """

    index: int
    activity_name: str
    activity_input: object = None
    _resolved: bool = False
    _result: object = None

    def is_resolved(self) -> bool:
        return self._resolved

    def resolve(self, value: object) -> None:
        self._resolved = True
        self._result = value

    def result(self) -> object:
        if not self._resolved:
            raise _NotReady(self.index)
        return self._result


class _NotReady(Exception):
    """Raised internally when an awaited task has no recorded result yet.

    The replay runner catches this to pause the orchestrator until the next
    activity completion is available in history.
    """

    def __init__(self, task_index: int) -> None:
        super().__init__(f"task {task_index} has no recorded result yet")
        self.task_index = task_index


@dataclass
class OrchestrationResult:
    """Terminal output of one orchestration plus the trail it produced."""

    status: str
    output: object = None
    instance_id: str = ""
    actions: list[Action] = field(default_factory=list)
    replays: int = 0
    reason: str = ""
    extra: dict = field(default_factory=dict)

    def action_signatures(self) -> list[tuple]:
        return [action.signature() for action in self.actions]

    def is_completed(self) -> bool:
        return self.status == "completed"


def _freeze(value: object) -> object:
    """Make a value hashable and order-revealing for fingerprinting.

    Dicts are frozen into sorted key/value tuples so that two dicts with the
    same contents compare equal regardless of insertion order; lists keep their
    order because order is meaningful for activity inputs and results.
    """

    if isinstance(value, dict):
        return tuple(sorted((k, _freeze(v)) for k, v in value.items()))
    if isinstance(value, (list, tuple)):
        return tuple(_freeze(v) for v in value)
    if isinstance(value, set):
        return tuple(sorted(_freeze(v) for v in value))
    return value


def build_call_action(
    task_index: int, activity_name: str, activity_input: object
) -> Action:
    return Action(
        action_type=ActionType.CALL_ACTIVITY,
        task_index=task_index,
        activity_name=activity_name,
        activity_input=activity_input,
    )


def build_complete_action(task_index: int, payload: object) -> Action:
    return Action(
        action_type=ActionType.COMPLETE,
        task_index=task_index,
        payload=payload,
    )


def scheduled_event(task_index: int, activity_name: str, activity_input: object) -> HistoryEvent:
    return HistoryEvent(
        event_type=EventType.TASK_SCHEDULED,
        task_index=task_index,
        activity_name=activity_name,
        activity_input=activity_input,
    )


def completed_event(task_index: int, activity_name: str, result: object) -> HistoryEvent:
    return HistoryEvent(
        event_type=EventType.TASK_COMPLETED,
        task_index=task_index,
        activity_name=activity_name,
        result=result,
    )

